import java.util.Arrays;

/**
 * CandidateSolution.java
 *
 * Represents one candidate process-execution order generated by the QEA.
 *
 * A candidate solution is a permutation of process indices [0..n-1] that
 * defines the ORDER in which the scheduler should attempt to execute processes.
 * The QEA searches for the permutation that minimises the fitness function.
 *
 * Fields are intentionally package-accessible (not private) so that
 * QuantumInspiredOptimizer and FitnessFunction can operate efficiently
 * without getter overhead in the inner loop.
 *
 * @author  OSDS-CP Group
 * @version 1.0  (Phase 1)
 */
public class CandidateSolution implements Comparable<CandidateSolution> {

    // ── Core fields ───────────────────────────────────────────────────────────

    /**
     * The execution-order permutation.
     * order[0] is attempted first, order[n-1] is attempted last.
     * All values are distinct process indices in [0, n-1].
     */
    public final int[] order;

    /** Number of processes in this solution (= SystemState.numProcesses). */
    public final int n;

    // ── Evaluated fields (set by FitnessFunction) ─────────────────────────────

    /** Fitness value. Lower = better. Double.MAX_VALUE until evaluated. */
    public double fitness = Double.MAX_VALUE;

    /** True iff Banker's Algorithm confirmed this execution order is safe. */
    public boolean isSafe = false;

    /** Number of processes that successfully completed. */
    public int processesCompleted = 0;

    /** Total waiting time across all processes (rounded steps they were blocked). */
    public double totalWaitingTime = 0.0;

    /** Total idle (wasted) resource instances at end of simulation. */
    public double resourceWaste = 0.0;

    /**
     * The raw observed bit from each qubit (0 or 1) that produced this solution.
     * Stored so the rotation step can compare this solution against the best.
     * Length = n.
     */
    public final int[] observedBits;

    // ── Constructor ───────────────────────────────────────────────────────────

    /**
     * Constructs a CandidateSolution from a permutation and its source qubit bits.
     *
     * @param order        process-execution permutation (defensive copy taken)
     * @param observedBits raw qubit observations that produced this order
     */
    public CandidateSolution(int[] order, int[] observedBits) {
        if (order == null || order.length == 0)
            throw new IllegalArgumentException("CandidateSolution: order must not be null/empty.");
        this.n            = order.length;
        this.order        = order.clone();
        this.observedBits = (observedBits != null) ? observedBits.clone() : new int[n];
    }

    // ── Comparison ────────────────────────────────────────────────────────────

    /**
     * Natural order: lower fitness is better (used by sorting / priority queues).
     */
    @Override
    public int compareTo(CandidateSolution other) {
        return Double.compare(this.fitness, other.fitness);
    }

    /** Returns true iff this solution has a strictly better (lower) fitness. */
    public boolean isBetterThan(CandidateSolution other) {
        return this.fitness < other.fitness;
    }

    // ── Utility ───────────────────────────────────────────────────────────────

    /** Returns a deep copy (fitness and flags are copied too). */
    public CandidateSolution deepCopy() {
        CandidateSolution copy = new CandidateSolution(order, observedBits);
        copy.fitness           = this.fitness;
        copy.isSafe            = this.isSafe;
        copy.processesCompleted = this.processesCompleted;
        copy.totalWaitingTime  = this.totalWaitingTime;
        copy.resourceWaste     = this.resourceWaste;
        return copy;
    }

    @Override
    public String toString() {
        return String.format("CandidateSolution{order=%s, fitness=%.2f, safe=%b, completed=%d}",
            Arrays.toString(order), fitness, isSafe, processesCompleted);
    }
}
